"use client";

import { Meter as MeterPrimitive } from "@audio-ui/react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

const meterVariants = cva("", {
  defaultVariants: {
    size: "default",
  },
  variants: {
    size: {
      default: "h-48",
      lg: "h-64",
      sm: "h-32",
    },
  },
});

interface MeterProps
  extends MeterPrimitive.RootProps,
    VariantProps<typeof meterVariants> {
  peakMarks?: "visible" | "hidden";
}

export function Meter({
  className,
  size,
  peakMarks = "visible",
  ...props
}: MeterProps) {
  return (
    <MeterPrimitive.Root
      className={cn(
        "relative flex w-full select-none",
        "gap-1 data-[orientation=horizontal]:flex-col",
        meterVariants({ size }),
        className
      )}
      data-slot="meter"
      {...props}
    >
      <MeterPrimitive.Channels>
        {(_value, index) => (
          <MeterPrimitive.Channel
            className="rounded-[min(var(--radius-sm),6px)] bg-input/70 transition-shadow duration-150 ease-out data-[clip=true]:ring-2 data-[clip=true]:ring-destructive relative flex-1 overflow-hidden"
            index={index}
            key={`meter-channel-${index}`}
          >
            <MeterPrimitive.Fill className="bg-success data-[clip=true]:bg-destructive absolute inset-0" />
            {peakMarks === "visible" ? (
              <MeterPrimitive.Peak className="bg-foreground absolute data-[orientation=horizontal]:top-0 data-[orientation=horizontal]:bottom-0 data-[orientation=horizontal]:w-0.5 data-[orientation=vertical]:right-0 data-[orientation=vertical]:left-0 data-[orientation=vertical]:h-0.5" />
            ) : null}
          </MeterPrimitive.Channel>
        )}
      </MeterPrimitive.Channels>
    </MeterPrimitive.Root>
  );
}
